from pathlib import Path
import re, json

matrix = r'''const num=value=>{if(typeof value==='number')return Number.isFinite(value)?value:0;let raw=String(value??'').trim().replace(/\s|\$/g,'');if(!raw)return 0;if(raw.includes(',')&&raw.includes('.'))raw=raw.lastIndexOf(',')>raw.lastIndexOf('.')?raw.replace(/\./g,'').replace(',','.'):raw.replace(/,/g,'');else if(raw.includes(','))raw=raw.replace(',','.');else if(/^\d{1,3}(?:\.\d{3})+$/.test(raw))raw=raw.replace(/\./g,'');const parsed=Number(raw);return Number.isFinite(parsed)?parsed:0};
const peso=value=>Math.round(num(value));
const round3=value=>Math.round(num(value)*1000)/1000;
const totalsOf=raw=>({net:Math.max(0,peso(raw?.net)),freight:Math.max(0,peso(raw?.freight)),vat:Math.max(0,peso(raw?.vat??raw?.tax)),additionalTax:Math.max(0,peso(raw?.additionalTax)),other:Math.max(0,peso(raw?.other)),total:Math.max(0,peso(raw?.total))});
const sum=(items,key)=>items.reduce((total,item)=>total+Math.max(0,peso(item[key])),0);
function integerShares(total,weights){const target=Math.max(0,peso(total)),safe=weights.map(v=>Math.max(0,num(v))),basis=safe.reduce((a,b)=>a+b,0);if(!target)return safe.map(()=>0);if(!basis){const base=Math.floor(target/Math.max(1,safe.length)),out=safe.map(()=>base);for(let i=0;i<target-base*out.length;i++)out[i%out.length]++;return out}const exact=safe.map(v=>target*v/basis),out=exact.map(Math.floor),left=target-out.reduce((a,b)=>a+b,0),rank=exact.map((v,i)=>({i,f:v-out[i]})).sort((a,b)=>b.f-a.f||a.i-b.i);for(let i=0;i<left;i++)out[rank[i%rank.length].i]++;return out}
function rebalance(lines,key,target,weights,adjustments){target=Math.max(0,peso(target));const before=lines.map(line=>Math.max(0,peso(line[key]))),current=before.reduce((a,b)=>a+b,0);if(current===target)return before;if(!lines.length)return before;let next;if(current>target&&current>0)next=integerShares(target,before);else{next=[...before];let residual=target-current;if(residual>0){const missing=before.map((v,i)=>({v,i})).filter(x=>x.v===0).map(x=>x.i),indexes=missing.length?missing:before.map((_,i)=>i),shares=integerShares(residual,indexes.map(i=>weights[i]||1));indexes.forEach((idx,j)=>next[idx]+=shares[j])}else if(residual<0)next=integerShares(target,before)}if(next.some((v,i)=>v!==before[i]))adjustments.push({column:key,before:current,target,delta:target-current});lines.forEach((line,i)=>line[key]=next[i]);return next}
function deriveNet(line){const explicit=Math.max(0,peso(line.netLineTotal));if(explicit)return explicit;const unit=Math.max(0,num(line.unitPriceNet)),qty=Math.max(0,num(line.invoiceQuantity??line.packageQty)),discount=Math.max(0,Math.min(100,num(line.discountPct)));return unit&&qty?Math.max(0,peso(unit*qty*(1-discount/100))):0}
export function reconcileInvoicePricing(lines,rawTotals,warnings=[]){
  const totals=totalsOf(rawTotals),priced=lines.filter(line=>!line.isFree&&Math.max(0,num(line.totalUnits??line.units))>0),printed=priced.filter(line=>Math.max(0,num(line.printedFinalUnitPrice??line.finalUnitPrice))>0&&String(line.priceSource||'')==='printed-final-unit'),tol=Math.max(2,Math.round(Math.max(1,totals.total)*.0001));
  if(printed.length===priced.length&&printed.length){const exact=printed.reduce((s,line)=>s+num(line.printedFinalUnitPrice??line.finalUnitPrice)*num(line.totalUnits??line.units),0),delta=totals.total?round3(totals.total-exact):0,verified=!totals.total||Math.abs(delta)<=tol;printed.forEach(line=>{const units=num(line.totalUnits??line.units),qty=num(line.invoiceQuantity??line.packageQty),gross=peso(num(line.printedFinalUnitPrice??line.finalUnitPrice)*units);line.grossLineTotal=gross;line.grossUnitPrice=round3(gross/Math.max(1,units));line.grossPackPrice=qty?round3(gross/qty):0;line.priceVerified=verified;line.priceSource='printed-final-unit';line.taxAllocationMethod='supplier-printed-final-unit';line.priceBreakdown={gross,printedUnit:num(line.printedFinalUnitPrice??line.finalUnitPrice)}});if(verified)return{verified:true,method:'printed-final-unit-column',totals,documentTotalComputed:peso(exact),checksumDelta:delta,matrix:{source:'printed-final-unit',rows:printed.length}};warnings.push(`El precio final impreso no cierra contra el total del documento (${Math.round(exact)} vs ${totals.total}); Nuvasto usará la matriz de cargos de la factura.`)}
  if(!priced.length)return{verified:false,method:'no-priced-lines',totals,documentTotalComputed:0,checksumDelta:totals.total};
  for(const line of priced){line.netLineTotal=deriveNet(line);line.freightLine=Math.max(0,peso(line.freightLine??line.freightLineTotal));line.vatLine=Math.max(0,peso(line.vatLine??line.taxLineTotal));line.additionalTaxLine=Math.max(0,peso(line.additionalTaxLine??line.additionalTaxLineTotal));line.otherLineCharges=Math.max(0,peso(line.otherLineCharges));}
  const weights=priced.map(line=>Math.max(1,line.netLineTotal||num(line.invoiceQuantity)||1)),initial={net:sum(priced,'netLineTotal'),freight:sum(priced,'freightLine'),vat:sum(priced,'vatLine'),additionalTax:sum(priced,'additionalTaxLine'),other:sum(priced,'otherLineCharges')},adjustments=[];
  let targetNet=totals.total?Math.max(0,totals.total-totals.freight-totals.vat-totals.additionalTax-totals.other):totals.net;if(!targetNet&&totals.net)targetNet=Math.max(0,totals.net-(totals.freight&&totals.net>=totals.freight?totals.freight:0));if(totals.net&&Math.abs(totals.net-initial.net)<=Math.abs(targetNet-initial.net))targetNet=totals.net;
  rebalance(priced,'netLineTotal',targetNet,weights,adjustments);rebalance(priced,'freightLine',totals.freight,weights,adjustments);rebalance(priced,'vatLine',totals.vat,priced.map(line=>Math.max(1,line.netLineTotal+line.freightLine)),adjustments);rebalance(priced,'additionalTaxLine',totals.additionalTax,priced.map(line=>Math.max(1,line.netLineTotal)),adjustments);rebalance(priced,'otherLineCharges',totals.other,weights,adjustments);
  for(const line of priced){const units=Math.max(0,num(line.totalUnits??line.units)),qty=Math.max(0,num(line.invoiceQuantity??line.packageQty));line.allocatedFreight=line.freightLine;line.allocatedVat=line.vatLine;line.allocatedAdditionalTax=line.additionalTaxLine;line.allocatedOtherCharges=line.otherLineCharges;line.grossLineTotal=line.netLineTotal+line.freightLine+line.vatLine+line.additionalTaxLine+line.otherLineCharges;line.grossUnitPrice=units?round3(line.grossLineTotal/units):0;line.grossPackPrice=qty?round3(line.grossLineTotal/qty):0;line.priceSource=adjustments.length?'invoice-matrix-reconciled':'invoice-line-matrix';line.taxAllocationMethod=adjustments.length?'column-total-reconciliation':'printed-line-components';line.priceBreakdown={net:line.netLineTotal,freight:line.freightLine,vat:line.vatLine,additionalTax:line.additionalTaxLine,other:line.otherLineCharges,gross:line.grossLineTotal};}
  const computed=priced.reduce((s,line)=>s+line.grossLineTotal,0),delta=totals.total?totals.total-computed:0,verified=!totals.total||Math.abs(delta)<=1;priced.forEach(line=>line.priceVerified=verified);if(adjustments.length)warnings.push(`Nuvasto cerró la matriz del documento contra sus totales impresos ajustando únicamente las columnas con diferencia: ${adjustments.map(item=>item.column).join(', ')}.`);if(!verified)warnings.push(`La matriz de precios no cierra: total impreso ${totals.total}, reconstruido ${computed}.`);return{verified,method:adjustments.length?'invoice-column-matrix-reconciled':'invoice-line-component-matrix',totals,documentTotalComputed:computed,checksumDelta:delta,matrix:{initial,targets:{net:targetNet,freight:totals.freight,vat:totals.vat,additionalTax:totals.additionalTax,other:totals.other},adjustments}};
}
'''
Path('professional/worker/src/invoice-pricing-matrix.js').write_text(matrix)

